#include <iostream>
#include <limits>
#include <initializer_list>

int c, d, n, m, k, commonParty, must;

int minValue(std::initializer_list<int> numbers) {
    int minNumber = std::numeric_limits<int>::max();

    for (int number : numbers) {
        minNumber = (number < minNumber) ? number : minNumber;
    }

    return minNumber;
}

int algC() {
    int tempCommonParty = must;
    int sumTask = 0;

    while (tempCommonParty > 0) {
        tempCommonParty -= n;
        sumTask += c;
    }

    return sumTask;
}

int algD() {
    int tempCommonParty = must;
    int sumTask = 0;

    while (tempCommonParty > 0) {
        tempCommonParty -= 1;
        sumTask += d;
    }

    return sumTask;
}

int algFull() {
    int resultC = algC();
    int resultD = algD();

    int sumTask = resultC - n;
    int partyCMinusRound = resultC * (n - 1);

    int i = must - partyCMinusRound;
    while (i > 0) {
        i -= 1;
        sumTask += d;
    }

    return minValue({resultC, resultD, sumTask});
}

