        int partyCMinusRound = (algJoint / c) * n;

        int i = must - partyCMinusRound;
        while (i > 0) {
            i -= 1;
            algJoint += d;
        }

        std::cout << minValue({resultC, resultD, algJoint}) << '\n';
    } else {
        std::cout << 0 << '\n';
    }

    return 0;
}

